1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。
17	// - 管理入口 GET /__contractlab/requests 查询本次进程内的请求记录（一致快照、
18	//   不推进序列），POST /__contractlab/requests/clear 清空记录；记录只存在内存中，
19	//   管理范围（/__contractlab 本身及 /__contractlab/ 前缀）的请求一律不记录。
20	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
21	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
22	
23	import http from 'node:http';
24	import { readFile } from 'node:fs/promises';
25	import path from 'node:path';
26	
27	const APP_NAME = 'contractlab';
28	
29	// 管理入口（保留前缀，业务接口不得使用）
30	const ADMIN_PREFIX = '/__contractlab/';
31	const ADMIN_BASE = '/__contractlab';
32	const HEALTH_PATH = '/__contractlab/health';
33	const RELOAD_PATH = '/__contractlab/reload';
34	const REQUESTS_PATH = '/__contractlab/requests';
35	const REQUESTS_CLEAR_PATH = '/__contractlab/requests/clear';
36	
37	// 每个业务响应都携带当前配置版本
38	const VERSION_HEADER = 'X-Contractlab-Version';
39	
40	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
41	const MAX_BODY_BYTES = 100 * 1024 * 1024;
42	
43	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
44	const BLOCKED_HEADERS = new Set([
45	  'connection',
46	  'keep-alive',
47	  'content-length',
48	  'transfer-encoding',
49	]);
50	
51	// RFC 7230 token：合法的 HTTP 头名称字符
52	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
53	
54	type HttpMethod = 'GET' | 'POST';
55	
56	// ---------------------------------------------------------------------------
57	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
58	// ---------------------------------------------------------------------------
59	//
60	// 规则格式（JSON 对象，未知字段一律拒绝）：
61	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
62	//   { "type": "array", "items": <规则> }
63	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
64	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
65	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
66	// array 必须声明 items。
67	
68	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
69	
70	type BodyRule =
71	  | {
72	      readonly kind: 'object';
73	      readonly fields: ReadonlyMap<string, FieldRule>;
74	      readonly additionalProperties: boolean;
75	    }
76	  | { readonly kind: 'array'; readonly items: BodyRule }
77	  | { readonly kind: ScalarKind };
78	
79	interface FieldRule {
80	  readonly rule: BodyRule;
81	  readonly required: boolean;
82	}
83	
84	interface ResponseSpec {
85	  readonly status: number;
86	  readonly headers: { readonly [name: string]: string };
87	  readonly body: string;
88	  readonly delay: number;
89	}
90	
91	interface EndpointSpec {
92	  readonly method: HttpMethod;
93	  readonly path: string;
94	  readonly responses: readonly ResponseSpec[];
95	  readonly bodyRule: BodyRule | undefined;
96	}
97	
98	interface LiveEndpoint {
99	  readonly key: string;
100	  readonly responses: readonly ResponseSpec[];
101	  readonly bodyRule: BodyRule | undefined;
102	  // 下一个待预留位置；到达末项后停在末项（持续复用）
103	  cursor: number;
104	}
105	
106	interface LiveState {
107	  readonly version: number;
108	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
109	}
110	
111	interface ReloadResult {
112	  ok: boolean;
113	  version: number;
114	  error?: string;
115	}
116	
117	class ConfigError extends Error {
118	  constructor(message: string) {
119	    super(message);
120	    this.name = 'ConfigError';
121	  }
122	}
123	
124	// ---------------------------------------------------------------------------
125	// 配置校验
126	// ---------------------------------------------------------------------------
127	
128	function isPlainObject(value: unknown): value is Record<string, unknown> {
129	  return typeof value === 'object' && value !== null && !Array.isArray(value);
130	}
131	
132	function validatePath(p: string, where: string): void {
133	  if (p.length === 0 || p[0] !== '/') {
134	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
135	  }
136	  if (p.length > 4096) {
137	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
138	  }
139	  for (const ch of p) {
140	    const code = ch.charCodeAt(0);
141	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
142	      throw new ConfigError(
143	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
144	      );
145	    }
146	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
147	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
148	    }
149	  }
150	}
151	
152	function validateResponse(raw: unknown, where: string): ResponseSpec {
153	  if (!isPlainObject(raw)) {
154	    throw new ConfigError(`${where} 必须是对象`);
155	  }
156	  for (const key of Object.keys(raw)) {
157	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
158	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
159	    }
160	  }
161	
162	  const { status, headers, body, delay } = raw;
163	
164	  if (!Number.isInteger(status) || status < 200 || status > 599) {
165	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
166	  }
167	
168	  if (!isPlainObject(headers)) {
169	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
170	  }
171	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
172	  const cleanHeaders: { [name: string]: string } = Object.create(null);
173	  const seenNames = new Set<string>();
174	  for (const [name, value] of Object.entries(headers)) {
175	    const whereHeader = `${where}.headers["${name}"]`;
176	    if (!HEADER_NAME_RE.test(name)) {
177	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
178	    }
179	    const lower = name.toLowerCase();
180	    if (BLOCKED_HEADERS.has(lower)) {
181	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
182	    }
183	    if (seenNames.has(lower)) {
184	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
185	    }
186	    if (typeof value !== 'string') {
187	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
188	    }
189	    for (let i = 0; i < value.length; i += 1) {
190	      const code = value.charCodeAt(i);
191	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
192	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
193	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
194	        throw new ConfigError(
195	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
196	        );
197	      }
198	    }
199	    seenNames.add(lower);
200	    cleanHeaders[name] = value;
201	  }
202	
203	  if (typeof body !== 'string') {
204	    throw new ConfigError(`${where}.body 必须是文本字符串`);
205	  }
206	  if ((status === 204 || status === 304) && body !== '') {
207	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
208	  }
209	
210	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
211	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
212	  }
213	
214	  return { status, headers: cleanHeaders, body, delay };
215	}
216	
217	const SCALAR_KINDS: ReadonlySet<string> = new Set([
218	  'string',
219	  'number',
220	  'integer',
221	  'boolean',
222	  'null',
223	]);
224	
225	function validateBodyRule(raw: unknown, where: string): BodyRule {
226	  if (!isPlainObject(raw)) {
227	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
228	  }
229	
230	  const type = raw.type;
231	  const allowed = new Set(['type']);
232	  if (type === 'object') {
233	    allowed.add('fields');
234	    allowed.add('additionalProperties');
235	  } else if (type === 'array') {
236	    allowed.add('items');
237	  } else if (!SCALAR_KINDS.has(type as string)) {
238	    throw new ConfigError(
239	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
240	    );
241	  }
242	  for (const key of Object.keys(raw)) {
243	    if (!allowed.has(key)) {
244	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
245	    }
246	  }
247	
248	  if (type === 'object') {
249	    const fieldsRaw = raw.fields;
250	    const fields = new Map<string, FieldRule>();
251	    if (fieldsRaw !== undefined) {
252	      if (!isPlainObject(fieldsRaw)) {
253	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
254	      }
255	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
256	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
257	      }
258	    }
259	    const additional = raw.additionalProperties;
260	    if (additional !== undefined && typeof additional !== 'boolean') {
261	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
262	    }
263	    // 未声明字段默认拒绝
264	    return { kind: 'object', fields, additionalProperties: additional === true };
265	  }
266	
267	  if (type === 'array') {
268	    if (raw.items === undefined) {
269	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
270	    }
271	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`) };
272	  }
273	
274	  return { kind: type as ScalarKind };
275	}
276	
277	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
278	function validateFieldRule(raw: unknown, where: string): FieldRule {
279	  if (!isPlainObject(raw)) {
280	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
281	  }
282	  let required = false;
283	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
284	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
285	  const rest: Record<string, unknown> = Object.create(null);
286	  for (const [key, value] of Object.entries(raw)) {
287	    if (key === 'required') {
288	      if (typeof value !== 'boolean') {
289	        throw new ConfigError(`${where}.required 必须是布尔值`);
290	      }
291	      required = value;
292	    } else {
293	      rest[key] = value;
294	    }
295	  }
296	  return { rule: validateBodyRule(rest, where), required };
297	}
298	
299	function validateEndpoint(
300	  raw: unknown,
301	  index: number,
302	  seen: Set<string>,
303	): EndpointSpec {
304	  const where = `endpoints[${index}]`;
305	  if (!isPlainObject(raw)) {
306	    throw new ConfigError(`${where} 必须是对象`);
307	  }
308	  for (const key of Object.keys(raw)) {
309	    if (key !== 'method' && key !== 'path' && key !== 'responses' && key !== 'requestBody') {
310	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
311	    }
312	  }
313	
314	  const { method, path: routePath, responses, requestBody } = raw;
315	
316	  if (method !== 'GET' && method !== 'POST') {
317	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
318	  }
319	
320	  if (typeof routePath !== 'string') {
321	    throw new ConfigError(`${where}.path 必须是字符串`);
322	  }
323	  validatePath(routePath, where);
324	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
325	    throw new ConfigError(
326	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
327	    );
328	  }
329	
330	  const key = `${method} ${routePath}`;
331	  if (seen.has(key)) {
332	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
333	  }
334	  seen.add(key);
335	
336	  if (!Array.isArray(responses) || responses.length === 0) {
337	    throw new ConfigError(`${where}.responses 必须是非空数组`);
338	  }
339	  const cleanResponses = responses.map((item, j) =>
340	    validateResponse(item, `${where}.responses[${j}]`),
341	  );
342	
343	  let bodyRule: BodyRule | undefined;
344	  if (requestBody !== undefined) {
345	    if (method !== 'POST') {
346	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
347	    }
348	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
349	  }
350	
351	  return { method, path: routePath, responses: cleanResponses, bodyRule };
352	}
353	
354	function validateConfig(raw: unknown): EndpointSpec[] {
355	  if (!isPlainObject(raw)) {
356	    throw new ConfigError('配置顶层必须是 JSON 对象');
357	  }
358	  for (const key of Object.keys(raw)) {
359	    if (key !== 'endpoints') {
360	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
361	    }
362	  }
363	  const list = raw.endpoints;
364	  if (!Array.isArray(list) || list.length === 0) {
365	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
366	  }
367	  const seen = new Set<string>();
368	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
369	}
370	
371	// ---------------------------------------------------------------------------
372	// 运行时状态：配置快照 + 每接口独立序列
373	// ---------------------------------------------------------------------------
374	
375	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
376	  const endpoints = new Map<string, LiveEndpoint>();
377	  for (const spec of specs) {
378	    endpoints.set(`${spec.method} ${spec.path}`, {
379	      key: `${spec.method} ${spec.path}`,
380	      responses: spec.responses,
381	      bodyRule: spec.bodyRule,
382	      cursor: 0,
383	    });
384	  }
385	  return { version, endpoints };
386	}
387	
388	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
389	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
390	// 返回本次消费位置（0 起）与该项；末项复用时位置停在 length-1。
391	function reserveNext(endpoint: LiveEndpoint): { position: number; item: ResponseSpec } {
392	  const last = endpoint.responses.length - 1;
393	  const position = endpoint.cursor < last ? endpoint.cursor : last;
394	  if (endpoint.cursor < last) {
395	    endpoint.cursor += 1;
396	  }
397	  return { position, item: endpoint.responses[position] };
398	}
399	
400	// ---------------------------------------------------------------------------
401	// 进程内请求记录
402	// ---------------------------------------------------------------------------
403	//
404	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
405	// 未收完整即断开或超出上限不创建记录、不消费序列。
406	// 编号按“完整接收”顺序在进程内单调递增，与接口消费位置是两回事；
407	// 清空与成功/失败重载都保留编号序列，编号不复用。记录只存在内存中，不写文件。
408	
409	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
410	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
411	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
412	//   interrupted —— 写出完成前连接断开或写入/发送失败
413	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
414	
415	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
416	interface PlannedResponseSnapshot {
417	  readonly kind: 'scene' | 'framework';
418	  readonly status: number;
419	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
420	  readonly headers: { readonly [name: string]: string };
421	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
422	  readonly body: string;
423	}
424	
425	interface RequestRecord {
426	  readonly id: number;
427	  readonly receivedAt: string;
428	  readonly request: {
429	    readonly method: string;
430	    // 含查询串的原始请求目标
431	    readonly target: string;
432	    readonly path: string;
433	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
434	    readonly rawHeaders: readonly string[];
435	    readonly bodyBytes: number;
436	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
437	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
438	  };
439	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
440	  configVersion: number;
441	  // matched=false：未匹配（404），不消费任何序列
442	  matched: boolean;
443	  endpoint: string | null;
444	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
445	  bodyValidationPassed: boolean | null;
446	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
447	  bodyRejection: BodyReport | null;
448	  // 场景请求在序列中的消费位置（0 起）；400/404 没有消费位置，记为 null
449	  sequencePosition: number | null;
450	  sequenceLength: number | null;
451	  plannedResponse: PlannedResponseSnapshot | null;
452	  delivery: DeliveryStatus;
453	}
454	
455	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
456	class RequestLog {
457	  private records: RequestRecord[] = [];
458	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
459	  private readonly live = new Map<number, RequestRecord>();
460	  private nextId = 1;
461	
462	  create(entry: {
463	    method: string;
464	    target: string;
465	    path: string;
466	    rawHeaders: readonly string[];
467	    body: Buffer;
468	    configVersion: number;
469	  }): RequestRecord {
470	    const id = this.nextId;
471	    this.nextId += 1;
472	    const record: RequestRecord = {
473	      id,
474	      receivedAt: new Date().toISOString(),
475	      request: {
476	        method: entry.method,
477	        target: entry.target,
478	        path: entry.path,
479	        rawHeaders: entry.rawHeaders,
480	        bodyBytes: entry.body.byteLength,
481	        body: encodeBodyLosslessly(entry.body),
482	      },
483	      configVersion: entry.configVersion,
484	      matched: false,
485	      endpoint: null,
486	      bodyValidationPassed: null,
487	      bodyRejection: null,
488	      sequencePosition: null,
489	      sequenceLength: null,
490	      plannedResponse: null,
491	      delivery: 'pending',
492	    };
493	    this.records.push(record);
494	    this.live.set(id, record);
495	    return record;
496	  }
497	
498	  // 写出完成；对已清空（不再存活）的记录是 no-op
499	  markDelivered(id: number, status: DeliveryStatus): void {
500	    const record = this.live.get(id);
501	    if (!record) {
502	      return;
503	    }
504	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
505	    if (record.delivery === 'sent') {
506	      return;
507	    }
508	    record.delivery = status;
509	  }
510	
511	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
512	  snapshot(): readonly RequestRecord[] {
513	    return [...this.records];
514	  }
515	
516	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
517	  // 清空前已完整接收的请求随后完成或失败都不再出现。
518	  clear(): number {
519	    const removed = this.records.length;
520	    this.records = [];
521	    this.live.clear();
522	    return removed;
523	  }
524	}
