526	// 原始正文字节的无损文本表示：先尝试严格 UTF-8；失败则用 base64 承载任意字节。
527	// 记录的是原始字节而非解析后的 JSON，避免任何信息损失。
528	function encodeBodyLosslessly(body: Buffer): { encoding: 'utf-8' | 'base64'; content: string } {
529	  try {
530	    const text = new TextDecoder('utf-8', { fatal: true }).decode(body);
531	    return { encoding: 'utf-8', content: text };
532	  } catch {
533	    return { encoding: 'base64', content: body.toString('base64') };
534	  }
535	}
