537	// ---------------------------------------------------------------------------
538	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
539	// ---------------------------------------------------------------------------
540	
541	interface StructureProblem {
542	  readonly pointer: string;
543	  readonly expected: string;
544	  readonly actual: string;
545	}
546	
547	interface BodyReport {
548	  readonly error: 'invalid_request_body';
549	  readonly stage: 'parse' | 'structure';
550	  readonly message: string;
551	  readonly problems: readonly StructureProblem[];
552	}
553	
554	function parseFailure(message: string): BodyReport {
555	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
556	}
557	
558	function jsonTypeOf(value: unknown): string {
559	  if (value === null) {
560	    return 'null';
561	  }
562	  if (Array.isArray(value)) {
563	    return 'array';
564	  }
565	  return typeof value;
566	}
567	
568	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
569	function escapePointerSegment(segment: string): string {
570	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
571	}
572	
573	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
574	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
575	function checkRule(
576	  rule: BodyRule,
577	  value: unknown,
578	  pointer: string,
579	  problems: StructureProblem[],
580	): void {
581	  switch (rule.kind) {
582	    case 'string':
583	    case 'boolean':
584	      if (typeof value !== rule.kind) {
585	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
586	      }
587	      return;
588	    case 'null':
589	      if (value !== null) {
590	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
591	      }
592	      return;
593	    case 'number':
594	      if (typeof value !== 'number' || !Number.isFinite(value)) {
595	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
596	      }
597	      return;
598	    case 'integer':
599	      if (!Number.isInteger(value)) {
600	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
601	      }
602	      return;
603	    case 'array': {
604	      if (!Array.isArray(value)) {
605	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
606	        return;
607	      }
608	      for (let i = 0; i < value.length; i += 1) {
609	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
610	      }
611	      return;
612	    }
613	    case 'object': {
614	      if (!isPlainObject(value)) {
615	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
616	        return;
617	      }
618	      for (const [name, field] of rule.fields) {
619	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
620	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
621	          if (field.required) {
622	            problems.push({
623	              pointer: childPointer,
624	              expected: `${field.rule.kind}（必填字段）`,
625	              actual: 'missing',
626	            });
627	          }
628	        } else {
629	          checkRule(field.rule, value[name], childPointer, problems);
630	        }
631	      }
632	      if (!rule.additionalProperties) {
633	        for (const key of Object.keys(value)) {
634	          if (!rule.fields.has(key)) {
635	            problems.push({
636	              pointer: `${pointer}/${escapePointerSegment(key)}`,
637	              expected: '未声明的字段（不允许）',
638	              actual: jsonTypeOf(value[key]),
639	            });
640	          }
641	        }
642	      }
643	      return;
644	    }
645	  }
646	}
647	
648	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告
649	function validateRequestBody(
650	  req: http.IncomingMessage,
651	  body: Buffer,
652	  rule: BodyRule,
653	): BodyReport | null {
654	  const contentType = req.headers['content-type'];
655	  const mediaType =
656	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
657	  if (mediaType !== 'application/json') {
658	    return parseFailure(
659	      typeof contentType === 'string'
660	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
661	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
662	    );
663	  }
664	
665	  if (body.length === 0) {
666	    return parseFailure('请求正文为空，无法解析为 JSON');
667	  }
668	
669	  let text: string;
670	  try {
671	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
672	  } catch {
673	    return parseFailure('请求正文不是合法的 UTF-8 编码');
674	  }
675	
676	  let parsed: unknown;
677	  try {
678	    parsed = JSON.parse(text);
679	  } catch (e) {
680	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
681	  }
682	
683	  const problems: StructureProblem[] = [];
684	  checkRule(rule, parsed, '', problems);
685	  if (problems.length > 0) {
686	    return {
687	      error: 'invalid_request_body',
688	      stage: 'structure',
689	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
690	      problems,
691	    };
692	  }
693	  return null;
694	}
