704	// 读取 -> 解析 -> 严格校验；任何一步失败都抛出含文件路径与可定位原因的错误
705	async function loadSpecsFromFile(configPath: string): Promise<EndpointSpec[]> {
706	  let text: string;
707	  try {
708	    text = await readFile(configPath, 'utf8');
709	  } catch (e) {
710	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
711	  }
712	
713	  let raw: unknown;
714	  try {
715	    raw = JSON.parse(text);
716	  } catch (e) {
717	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
718	  }
719	
720	  try {
721	    return validateConfig(raw);
722	  } catch (e) {
723	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
724	  }
