1138	function writeResponse(
1139	  res: http.ServerResponse,
1140	  status: number,
1141	  headers: { readonly [name: string]: string },
1142	  body: string,
1143	): void {
1144	  try {
1145	    res.writeHead(status, headers);
1146	    res.end(body === '' ? undefined : body);
1147	  } catch {
1148	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
1149	  }
1150	}
1151	
1152	function versionHeaders(
1153	  version: number,
1154	  extra?: { readonly [name: string]: string },
1155	): { [name: string]: string } {
1156	  // 无原型对象：配置中名为 "__proto__" 的响应头在合并时不丢失
1157	  const headers: { [name: string]: string } = Object.create(null);
1158	  headers[VERSION_HEADER] = String(version);
1159	  if (extra) {
1160	    for (const [name, value] of Object.entries(extra)) {
1161	      headers[name] = value;
1162	    }
1163	  }
1164	  return headers;
1165	}
