1167	function sendJson(res: http.ServerResponse, status: number, value: unknown, version: number): void {
1168	  writeResponse(
1169	    res,
1170	    status,
1171	    versionHeaders(version, { 'Content-Type': 'application/json; charset=utf-8' }),
1172	    `${JSON.stringify(value)}\n`,
1173	  );
1174	}
