1176	function sendNotFound(res: http.ServerResponse): void {
1177	  writeResponse(
1178	    res,
1179	    404,
1180	    versionHeaders(activeState.version, {
1181	      'Content-Type': 'text/plain; charset=utf-8',
1182	    }),
1183	    'not found\n',
1184	  );
1185	}
