1248	// 按计划快照写出；writeHead/end 在已断开套接字上抛错时标记为中断（消费已成立）。
1249	function writePlanned(
1250	  res: http.ServerResponse,
1251	  planned: PlannedResponseSnapshot,
1252	  recordId: number,
1253	): void {
1254	  try {
1255	    res.writeHead(planned.status, { ...planned.headers });
1256	    res.end(planned.body === '' ? undefined : planned.body);
1257	  } catch {
1258	    requestLog.markDelivered(recordId, 'interrupted');
1259	  }
1260	}
1261	
1262	// 挂载一次写出生命周期跟踪。每个被记录的请求恰好回复一次，故在接收完成后立即挂载：
1263	// 延迟期间断开也能标为中断；'sent' 为终态，随后连接正常关闭不回退。
1264	function attachDeliveryTracking(res: http.ServerResponse, recordId: number): void {
1265	  let settled = false;
1266	  const settle = (status: DeliveryStatus): void => {
1267	    if (settled) {
1268	      return;
1269	    }
1270	    settled = true;
1271	    requestLog.markDelivered(recordId, status);
1272	  };
1273	  res.once('finish', () => settle('sent'));
1274	  res.once('close', () => settle(res.writableFinished ? 'sent' : 'interrupted'));
1275	  res.once('error', () => settle('interrupted'));
1276	}
1277	
1278	// 延迟结束才按接收时的计划快照发送；即便客户端提前断开也继续计时（消费在预留时已成立）
1279	function schedulePlannedResponse(
1280	  res: http.ServerResponse,
1281	  planned: PlannedResponseSnapshot,
1282	  delay: number,
1283	  recordId: number,
1284	): void {
1285	  const timer = setTimeout(() => {
1286	    pendingTimers.delete(timer);
1287	    writePlanned(res, planned, recordId);
1288	  }, delay);
1289	  pendingTimers.add(timer);
1290	}
