1292	type BodyOutcome = 'received' | 'aborted' | 'too-large';
1293	
1294	interface ReceivedBody {
1295	  readonly outcome: BodyOutcome;
1296	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
1297	  readonly body: Buffer;
1298	}
1299	
1300	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
1301	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
1302	  return new Promise((resolve) => {
1303	    let settled = false;
1304	    let size = 0;
1305	    const chunks: Buffer[] = [];
1306	    const finish = (outcome: BodyOutcome): void => {
1307	      if (!settled) {
1308	        settled = true;
1309	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
1310	      }
1311	    };
1312	    req.on('data', (chunk: Buffer) => {
1313	      size += chunk.byteLength;
1314	      if (size > MAX_BODY_BYTES) {
1315	        finish('too-large');
1316	        writeResponse(
1317	          res,
1318	          413,
1319	          versionHeaders(activeState.version, {
1320	            'Content-Type': 'text/plain; charset=utf-8',
1321	          }),
1322	          'payload too large\n',
1323	        );
1324	        // 等 413 刷出后再断开，避免客户端收不到响应
1325	        res.once('finish', () => req.socket.destroy());
1326	        return;
1327	      }
1328	      chunks.push(chunk);
1329	    });
1330	    req.on('end', () => finish('received'));
1331	    req.on('error', () => finish('aborted'));
1332	    req.on('aborted', () => finish('aborted'));
1333	    res.on('close', () => finish('aborted'));
1334	  });
1335	}
1336	
1337	async function dispatch(
1338	  req: http.IncomingMessage,
1339	  res: http.ServerResponse,
1340	): Promise<void> {
1341	  res.on('error', () => {
1342	    // 写已销毁套接字等错误无需让进程崩溃
1343	  });
1344	
1345	  const method = String(req.method);
1346	  const target = String(req.url ?? '/'); // 含查询串的原始请求目标
1347	  const pathname = target.split('?')[0]; // 查询串不参与匹配
1348	
1349	  const { outcome, body } = await receiveBody(req, res);
1350	  if (outcome !== 'received') {
1351	    // aborted：未完整接收，不匹配、不预留、不推进任何序列，也不创建记录
1352	    // too-large：已回复 413，不创建记录、不消费序列
1353	    return;
1354	  }
1355	
1356	  // 管理范围：/__contractlab 本身及 /__contractlab/ 前缀。
1357	  // 其中所有请求都不记录、不消费业务序列（含未知子路径的 404）。
1358	  if (pathname === ADMIN_BASE || pathname.startsWith(ADMIN_PREFIX)) {
1359	    await handleAdmin(method, pathname, res);
1360	    return;
1361	  }
1362	
1363	  // 完整接收且不在管理范围：此刻创建记录并取得进程内递增编号。
1364	  // 编号只取决于完整接收顺序，与接口序列的消费位置互不相关。
1365	  const state = activeState;
1366	  const record = requestLog.create({
1367	    method,
1368	    target,
1369	    path: pathname,
1370	    rawHeaders: req.rawHeaders,
1371	    body,
1372	    configVersion: state.version,
1373	  });
1374	  attachDeliveryTracking(res, record.id);
1375	
1376	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
1377	  const endpoint =
1378	    method === 'GET' || method === 'POST'
1379	      ? state.endpoints.get(`${method} ${pathname}`)
1380	      : undefined;
1381	
1382	  if (!endpoint) {
1383	    // 未匹配请求：404，不消费、无消费位置
1384	    record.matched = false;
1385	    record.endpoint = `${method} ${pathname}`;
1386	    const planned = buildFrameworkPlanned(
1387	      404,
1388	      state.version,
1389	      'not found\n',
1390	      'text/plain; charset=utf-8',
1391	    );
1392	    record.plannedResponse = planned;
1393	    writePlanned(res, planned, record.id);
1394	    return;
1395	  }
1396	  record.matched = true;
1397	  record.endpoint = endpoint.key;
1398	
1399	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
1400	  // 规则、序列与版本均取自上面同一快照 state。
1401	  if (endpoint.bodyRule) {
1402	    const report = validateRequestBody(req, body, endpoint.bodyRule);
1403	    if (report) {
1404	      record.bodyValidationPassed = false;
1405	      record.bodyRejection = report;
1406	      const planned = buildFrameworkPlanned(
1407	        400,
1408	        state.version,
1409	        `${JSON.stringify(report)}\n`,
1410	        'application/json; charset=utf-8',
1411	      );
1412	      record.plannedResponse = planned;
1413	      writePlanned(res, planned, record.id);
1414	      return;
1415	    }
1416	    record.bodyValidationPassed = true;
1417	  }
1418	
1419	  // 校验通过（或无规则）：立即预留，并把消费位置与场景计划响应记入同一条记录
1420	  const { position, item } = reserveNext(endpoint);
1421	  record.sequencePosition = position;
1422	  record.sequenceLength = endpoint.responses.length;
1423	  const planned = buildScenePlanned(item, state.version);
1424	  record.plannedResponse = planned;
1425	  schedulePlannedResponse(res, planned, item.delay, record.id);
1426	}
