1500	function shutdown(): void {
1501	  if (shuttingDown) {
1502	    return;
1503	  }
1504	  shuttingDown = true;
1505	  // 取消所有尚未发出的延迟响应
1506	  for (const timer of pendingTimers) {
1507	    clearTimeout(timer);
1508	  }
1509	  pendingTimers.clear();
1510	  // 关闭监听并断开空闲/在途连接，随后正常退出（退出码 0）
1511	  try {
1512	    server.closeAllConnections();
1513	  } catch {
1514	    // 旧版本兜底：忽略，下面的 close/超时仍会结束进程
1515	  }
1516	  server.close(() => process.exit(0));
1517	  setTimeout(() => process.exit(0), 2000).unref();
1518	}
